import {
  Button,
  Checkbox,
  Group,
  PasswordInput,
  SimpleGrid,
  Stack,
  TextInput,
} from '@mantine/core';
import { FormErrors, isEmail, isNotEmpty, matchesField, useForm } from '@mantine/form';
import { notifications } from '@mantine/notifications';
import { PasswordInputWithRequirements, validatePassword } from './PasswordInputWithRequirements';

interface RegistrationValues {
  firstName: string;
  lastName: string;
  email: string;
  password: string;
  confirmPassword: string;
  terms: boolean;
}

function register(values: RegistrationValues) {
  return new Promise<RegistrationValues>((resolve) => {
    setTimeout(() => resolve(values), 1500);
  });
}

export function RegistrationForm() {
  const form = useForm<RegistrationValues>({
    initialValues: {
      firstName: '',
      lastName: '',
      email: '',
      password: '',
      confirmPassword: '',
      terms: false,
    },
    validate: {
      firstName: isNotEmpty('First name is required'),
      lastName: isNotEmpty('Last name is required'),
      email: isEmail('Invalid email'),
      password: validatePassword,
      confirmPassword: matchesField('password', 'Passwords do not match'),
      terms: isNotEmpty('You must accept terms and conditions'),
    },
  });

  form.watch('password', () => {
    if (form.errors.confirmPassword) {
      form.validateField('confirmPassword');
    }
  });

  const handleSubmit = async (values: RegistrationValues) => {
    const user = await register(values);
    notifications.show({
      title: 'Account created',
      message: `${user.firstName} ${user.lastName} (${user.email}) can now sign in`,
    });
  };

  const handleErrors = (errors: FormErrors) => {
    form.getInputNode(Object.keys(errors)[0])?.focus();
  };

  return (
    <form onSubmit={form.onSubmit(handleSubmit, handleErrors)}>
      <Stack>
        <SimpleGrid cols={{ base: 1, sm: 2 }}>
          <TextInput
            size="md"
            label="First name"
            placeholder="John"
            withAsterisk
            {...form.getInputProps('firstName')}
          />

          <TextInput
            size="md"
            label="Last name"
            placeholder="Doe"
            withAsterisk
            {...form.getInputProps('lastName')}
          />
        </SimpleGrid>

        <TextInput
          size="md"
          label="Email"
          placeholder="you@mantine.dev"
          withAsterisk
          {...form.getInputProps('email')}
        />

        <PasswordInputWithRequirements form={form} />

        <PasswordInput
          size="md"
          label="Confirm password"
          placeholder="Repeat your password"
          withAsterisk
          {...form.getInputProps('confirmPassword')}
        />

        <Checkbox
          size="md"
          label="I accept terms and conditions"
          {...form.getInputProps('terms', { type: 'checkbox' })}
        />

        <Group justify="flex-end">
          <Button size="md" type="submit" loading={form.submitting}>
            Create account
          </Button>
        </Group>
      </Stack>
    </form>
  );
}

import { useState } from 'react';
import { CheckIcon, XIcon } from '@phosphor-icons/react';
import { Group, PasswordInput, Popover, Stack, Text } from '@mantine/core';
import { UseFormReturnType } from '@mantine/form';

export const passwordRequirements = [
  { label: 'At least 8 characters', test: (value: string) => value.length >= 8 },
  { label: 'Includes a number', test: (value: string) => /[0-9]/.test(value) },
  { label: 'Includes an uppercase letter', test: (value: string) => /[A-Z]/.test(value) },
];

export function validatePassword(value: string) {
  const failed = passwordRequirements.find((requirement) => !requirement.test(value));
  return failed ? `Password must satisfy: ${failed.label.toLowerCase()}` : null;
}

interface PasswordInputWithRequirementsProps {
  form: UseFormReturnType<{ password: string }>;
}

export function PasswordInputWithRequirements({ form }: PasswordInputWithRequirementsProps) {
  const [opened, setOpened] = useState(false);
  const password = form.useWatchValue('password');
  const inputProps = form.getInputProps('password');

  const checks = passwordRequirements.map((requirement) => {
    const passed = requirement.test(password);
    return (
      <Group key={requirement.label} gap="xs">
        {passed ? (
          <CheckIcon size={14} weight="bold" color="var(--mantine-color-success)" />
        ) : (
          <XIcon size={14} weight="bold" color="var(--mantine-color-error)" />
        )}
        <Text size="sm" c={passed ? 'var(--mantine-color-success)' : 'var(--mantine-color-error)'}>
          {requirement.label}
        </Text>
      </Group>
    );
  });

  return (
    <Popover
      opened={opened}
      position="bottom-start"
      width="target"
      transitionProps={{ duration: 0 }}
    >
      <Popover.Target>
        <PasswordInput
          size="md"
          label="Password"
          placeholder="Your password"
          withAsterisk
          {...inputProps}
          onFocus={(event) => {
            setOpened(true);
            inputProps.onFocus?.(event);
          }}
          onBlur={(event) => {
            setOpened(false);
            inputProps.onBlur?.(event);
          }}
        />
      </Popover.Target>
      <Popover.Dropdown>
        <Stack gap={6}>{checks}</Stack>
      </Popover.Dropdown>
    </Popover>
  );
}
